    { const char * tb_v985 = "static char *tb_win_getenv(const char *name) {\n"; *(const char * *)tb_grow(v_lines) = tb_v985; }
    { const char * tb_v986 = "    wchar_t *n = tb_wide(name);\n"; *(const char * *)tb_grow(v_lines) = tb_v986; }
