    { const char * tb_v991 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v991; }
    { const char * tb_v992 = "// cmd.exe /c убирает первую и последнюю кавычку, если кавычек больше двух:\n"; *(const char * *)tb_grow(v_lines) = tb_v992; }
    { const char * tb_v993 = "// поэтому команда целиком берётся ещё в одни кавычки\n"; *(const char * *)tb_grow(v_lines) = tb_v993; }
    { const char * tb_v994 = "static wchar_t *tb_win_cmd(const char *command) {\n"; *(const char * *)tb_grow(v_lines) = tb_v994; }
    { const char * tb_v995 = "    size_t n = strlen(command);\n"; *(const char * *)tb_grow(v_lines) = tb_v995; }
    { const char * tb_v996 = "    char *q = malloc(n + 3);\n"; *(const char * *)tb_grow(v_lines) = tb_v996; }
    { const char * tb_v997 = "    if (!q) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v997; }
    { const char * tb_v998 = "    q[0] = '\"'; memcpy(q + 1, command, n); q[n + 1] = '\"'; q[n + 2] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v998; }
    { const char * tb_v999 = "    wchar_t *w = tb_wide(q);\n"; *(const char * *)tb_grow(v_lines) = tb_v999; }
    { const char * tb_v1000 = "    free(q);\n"; *(const char * *)tb_grow(v_lines) = tb_v1000; }
    { const char * tb_v1001 = "    return w;\n"; *(const char * *)tb_grow(v_lines) = tb_v1001; }
    { const char * tb_v1002 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1002; }
    { const char * tb_v1003 = "static int tb_win_system(const char *command) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1003; }
    { const char * tb_v1004 = "    wchar_t *c = tb_win_cmd(command);\n"; *(const char * *)tb_grow(v_lines) = tb_v1004; }
    { const char * tb_v1005 = "    int r = c ? _wsystem(c) : -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v1005; }
    { const char * tb_v1006 = "    free(c);\n"; *(const char * *)tb_grow(v_lines) = tb_v1006; }
    { const char * tb_v1007 = "    return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v1007; }
    { const char * tb_v1008 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1008; }
    { const char * tb_v1009 = "static FILE *tb_win_popen(const char *command, const char *mode) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1009; }
    { const char * tb_v1010 = "    wchar_t *c = tb_win_cmd(command), *m = tb_wide(mode);\n"; *(const char * *)tb_grow(v_lines) = tb_v1010; }
    { const char * tb_v1011 = "    FILE *f = c && m ? _wpopen(c, m) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1011; }
