    { const char * tb_v1014 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1014; }
    { const char * tb_v1015 = "// папка: _wopendir / _wreaddir, имена — в UTF-8\n"; *(const char * *)tb_grow(v_lines) = tb_v1015; }
