    { const char * tb_v1073 = "#define TB_COLD __attribute__((cold, noreturn, noinline))\n"; *(const char * *)tb_grow(v_lines) = tb_v1073; }
    { const char * tb_v1074 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v1074; }
    { const char * tb_v1075 = "#define TB_RARE(x) (x)\n"; *(const char * *)tb_grow(v_lines) = tb_v1075; }
