    { const char * tb_v1077 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v1077; }
    { const char * tb_v1078 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v1078; }
    { const char * tb_v1079 = "// список: кусок памяти, len элементов по size байт, место на cap\n"; *(const char * *)tb_grow(v_lines) = tb_v1079; }
    { const char * tb_v1080 = "typedef struct { char *data; long long len; long long cap; long long size; } tb_list;\n"; *(const char * *)tb_grow(v_lines) = tb_v1080; }
    { const char * tb_v1081 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v1081; }
    { const char * tb_v1082 = "TB_COLD static void tb_crash(int line, const char *msg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1082; }
    { const char * tb_v1083 = "    fflush(stdout);\n"; *(const char * *)tb_grow(v_lines) = tb_v1083; }
    { const char * tb_v1084 = "    // в терминале — красным (если не задан NO_COLOR)\n"; *(const char * *)tb_grow(v_lines) = tb_v1084; }
    { const char * tb_v1085 = "    int color = isatty(2) && getenv(\"NO_COLOR\") == 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1085; }
    { const char * tb_v1086 = "    if (color) fputs(\"\\033[31m\", stderr);\n"; *(const char * *)tb_grow(v_lines) = tb_v1086; }
    { const char * tb_v1087 = "    if (line > 0) fprintf(stderr, \"строка %d: %s\", line, msg);\n"; *(const char * *)tb_grow(v_lines) = tb_v1087; }
    { const char * tb_v1088 = "    else fprintf(stderr, \"%s\", msg);\n"; *(const char * *)tb_grow(v_lines) = tb_v1088; }
    { const char * tb_v1089 = "    fputs(color ? \"\\033[0m\\n\" : \"\\n\", stderr);\n"; *(const char * *)tb_grow(v_lines) = tb_v1089; }
    { const char * tb_v1090 = "    exit(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v1090; }
    { const char * tb_v1091 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1091; }
    { const char * tb_v1092 = "#ifndef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v1092; }
    { const char * tb_v1093 = "// ---------- падение по памяти: понятное сообщение вместо «Segmentation fault» ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v1093; }
    { const char * tb_v1094 = "// Чаще всего это стек: функция зовёт себя слишком глубоко. Обработчик работает\n"; *(const char * *)tb_grow(v_lines) = tb_v1094; }
    { const char * tb_v1095 = "// на своём маленьком стеке (sigaltstack), потому что основной уже кончился.\n"; *(const char * *)tb_grow(v_lines) = tb_v1095; }
    { const char * tb_v1096 = "#ifndef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v1096; }
    { const char * tb_v1097 = "#include <signal.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v1097; }
    { const char * tb_v1098 = "#include <sys/resource.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v1098; }
    { const char * tb_v1099 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v1099; }
    { const char * tb_v1100 = "// На Windows нет сигналов и sigaltstack: переполнение стека ловит обработчик\n"; *(const char * *)tb_grow(v_lines) = tb_v1100; }
    { const char * tb_v1101 = "// исключений (tb_guard_init ниже), а место для него в конце стека даёт\n"; *(const char * *)tb_grow(v_lines) = tb_v1101; }
    { const char * tb_v1102 = "// SetThreadStackGuarantee. Этот sigaltstack только помнит память потока,\n"; *(const char * *)tb_grow(v_lines) = tb_v1102; }
    { const char * tb_v1103 = "// чтобы tb_tramp_run мог её отдать, и просит у Windows запас стека.\n"; *(const char * *)tb_grow(v_lines) = tb_v1103; }
    { const char * tb_v1104 = "typedef struct { void *ss_sp; size_t ss_size; int ss_flags; } stack_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v1104; }
    { const char * tb_v1105 = "#define SS_DISABLE 4\n"; *(const char * *)tb_grow(v_lines) = tb_v1105; }
    { const char * tb_v1106 = "static _Thread_local void *tb_win_alt;\n"; *(const char * *)tb_grow(v_lines) = tb_v1106; }
    { const char * tb_v1107 = "static int sigaltstack(const stack_t *ss, stack_t *old) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1107; }
    { const char * tb_v1108 = "    if (old) { old->ss_sp = tb_win_alt; old->ss_size = 0; old->ss_flags = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v1108; }
    { const char * tb_v1109 = "    if (ss) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1109; }
    { const char * tb_v1110 = "        tb_win_alt = (ss->ss_flags & SS_DISABLE) ? 0 : ss->ss_sp;\n"; *(const char * *)tb_grow(v_lines) = tb_v1110; }
    { const char * tb_v1111 = "        if (!(ss->ss_flags & SS_DISABLE)) { ULONG g = 65536; SetThreadStackGuarantee(&g); }\n"; *(const char * *)tb_grow(v_lines) = tb_v1111; }
    { const char * tb_v1112 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v1112; }
    { const char * tb_v1113 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1113; }
    { const char * tb_v1114 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1114; }
    { const char * tb_v1115 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v1115; }
    { const char * tb_v1116 = "// у каждого потока своё: где начинается его стек и сколько в нём места\n"; *(const char * *)tb_grow(v_lines) = tb_v1116; }
    { const char * tb_v1117 = "static _Thread_local char *tb_main_sp;\n"; *(const char * *)tb_grow(v_lines) = tb_v1117; }
    { const char * tb_v1118 = "static _Thread_local long long tb_stack_lim;\n"; *(const char * *)tb_grow(v_lines) = tb_v1118; }
    { const char * tb_v1119 = "#define TB_THREAD_STACK (8LL << 20)\n"; *(const char * *)tb_grow(v_lines) = tb_v1119; }
    { const char * tb_v1120 = "#ifndef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v1120; }
    { const char * tb_v1121 = "static void tb_on_segv(int sig, siginfo_t *si, void *u) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1121; }
    { const char * tb_v1122 = "    (void)sig; (void)u;\n"; *(const char * *)tb_grow(v_lines) = tb_v1122; }
    { const char * tb_v1123 = "    char *a = (char *)si->si_addr;\n"; *(const char * *)tb_grow(v_lines) = tb_v1123; }
    { const char * tb_v1124 = "    long long lim = tb_stack_lim;\n"; *(const char * *)tb_grow(v_lines) = tb_v1124; }
    { const char * tb_v1125 = "    if (lim == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1125; }
    { const char * tb_v1126 = "        lim = 8LL << 20;\n"; *(const char * *)tb_grow(v_lines) = tb_v1126; }
    { const char * tb_v1127 = "        struct rlimit rl;\n"; *(const char * *)tb_grow(v_lines) = tb_v1127; }
    { const char * tb_v1128 = "        if (getrlimit(RLIMIT_STACK, &rl) == 0 && rl.rlim_cur != RLIM_INFINITY) lim = (long long)rl.rlim_cur;\n"; *(const char * *)tb_grow(v_lines) = tb_v1128; }
    { const char * tb_v1129 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v1129; }
    { const char * tb_v1130 = "    const char *m;\n"; *(const char * *)tb_grow(v_lines) = tb_v1130; }
    { const char * tb_v1131 = "    if (tb_main_sp && a <= tb_main_sp + 65536 && a >= tb_main_sp - lim - (1 << 20))\n"; *(const char * *)tb_grow(v_lines) = tb_v1131; }
    { const char * tb_v1132 = "        m = \"стек переполнен: функция зовёт себя слишком глубоко (рекурсия без конца?)\\n\";\n"; *(const char * *)tb_grow(v_lines) = tb_v1132; }
    { const char * tb_v1133 = "    else\n"; *(const char * *)tb_grow(v_lines) = tb_v1133; }
    { const char * tb_v1134 = "        m = \"программа упала: ошибка памяти. Это ошибка Tachbit, а не твоя: пришли, пожалуйста, эту программу\\n\";\n"; *(const char * *)tb_grow(v_lines) = tb_v1134; }
    { const char * tb_v1135 = "    if (write(2, m, strlen(m)) < 0) _exit(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v1135; }
    { const char * tb_v1136 = "    _exit(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v1136; }
