    { const char * tb_v1400 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1400; }
    { const char * tb_v1401 = "static inline tb_gpage *tb_gmap_get(uintptr_t a) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1401; }
    { const char * tb_v1402 = "    if (a >> 48) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1402; }
