    { const char * tb_v1407 = "    tb_gpage ***d = &tb_gdir[a >> 32];\n"; *(const char * *)tb_grow(v_lines) = tb_v1407; }
    { const char * tb_v1408 = "    if (!*d) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1408; }
