    { const char * tb_v2295 = "// ---------- http_get: страница из интернета через curl (есть на Mac и почти на любом Linux) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2295; }
    { const char * tb_v2296 = "static const char *tb_http_get(const char *url) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2296; }
    { const char * tb_v2297 = "    if (strncmp(url, \"http://\", 7) != 0 && strncmp(url, \"https://\", 8) != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2297; }
    { const char * tb_v2298 = "        tb_err = tb_cat(\"адрес должен начинаться с http:// или https://: \", url);\n"; *(const char * *)tb_grow(v_lines) = tb_v2298; }
