    { const char * tb_v2492 = "static unsigned long long tb_rand_state = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2492; }
    { const char * tb_v2493 = "// цвет из красного, зелёного и синего (0..255) — одно число 0xRRGGBB\n"; *(const char * *)tb_grow(v_lines) = tb_v2493; }
    { const char * tb_v2494 = "static long long tb_rgb(long long r, long long g, long long b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2494; }
    { const char * tb_v2495 = "    r = r < 0 ? 0 : r > 255 ? 255 : r; g = g < 0 ? 0 : g > 255 ? 255 : g; b = b < 0 ? 0 : b > 255 ? 255 : b;\n"; *(const char * *)tb_grow(v_lines) = tb_v2495; }
