    { const char * tb_v2498 = "// случайное целое от a до b (оба входят)\n"; *(const char * *)tb_grow(v_lines) = tb_v2498; }
    { const char * tb_v2499 = "static long long tb_random(long long a, long long b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2499; }
    { const char * tb_v2500 = "    if (tb_rand_state == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2500; }
    { const char * tb_v2501 = "        struct timespec ts; clock_gettime(CLOCK_REALTIME, &ts);\n"; *(const char * *)tb_grow(v_lines) = tb_v2501; }
    { const char * tb_v2502 = "        tb_rand_state = ((unsigned long long)ts.tv_nsec << 20) ^ (unsigned long long)ts.tv_sec ^ 0x9E3779B97F4A7C15ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v2502; }
    { const char * tb_v2503 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2503; }
