    { const char * tb_v2534 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2534; }
    { const char * tb_v2535 = "// ---------- dict: ключи и значения лежат в двух списках по порядку добавления,\n"; *(const char * *)tb_grow(v_lines) = tb_v2535; }
    { const char * tb_v2536 = "// а найти номер по ключу можно тремя способами (mode):\n"; *(const char * *)tb_grow(v_lines) = tb_v2536; }
    { const char * tb_v2537 = "//   1 — «номер = адрес»: ключи int шли подряд base, base+1, base+2 ... — номер = ключ - base, без поиска;\n"; *(const char * *)tb_grow(v_lines) = tb_v2537; }
    { const char * tb_v2538 = "//   2 — «адресное хранение»: ключи int лежат плотно — pos[ключ - base] = номер + 1, один взгляд;\n"; *(const char * *)tb_grow(v_lines) = tb_v2538; }
    { const char * tb_v2539 = "//   0 — таблица slots с хешем (текст или разбросанные числа) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2539; }
    { const char * tb_v2540 = "typedef struct {\n"; *(const char * *)tb_grow(v_lines) = tb_v2540; }
