    { const char * tb_v2544 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2544; }
    { const char * tb_v2545 = "// ячейка таблицы: номер ключа + 1 (младшие 40 бит) и метка из старших битов хеша\n"; *(const char * *)tb_grow(v_lines) = tb_v2545; }
    { const char * tb_v2546 = "#define TB_DAT ((1LL << 40) - 1)\n"; *(const char * *)tb_grow(v_lines) = tb_v2546; }
    { const char * tb_v2547 = "#define TB_DTAG(h) ((long long)(((h) >> 40) << 40) & ~TB_DAT & 0x7FFFFFFFFFFFFFFFLL)\n"; *(const char * *)tb_grow(v_lines) = tb_v2547; }
    { const char * tb_v2548 = "static unsigned long long tb_hash(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2548; }
    { const char * tb_v2549 = "    unsigned long long h = 1469598103934665603ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v2549; }
    { const char * tb_v2550 = "    if (d->text) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2550; }
    { const char * tb_v2551 = "        for (const unsigned char *p = *(const unsigned char * const *)k; *p; p++) { h ^= *p; h *= 1099511628211ULL; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2551; }
    { const char * tb_v2552 = "    } else {\n"; *(const char * *)tb_grow(v_lines) = tb_v2552; }
    { const char * tb_v2553 = "        h ^= (unsigned long long)*(const long long *)k;\n"; *(const char * *)tb_grow(v_lines) = tb_v2553; }
    { const char * tb_v2554 = "        h *= 0x9E3779B97F4A7C15ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v2554; }
    { const char * tb_v2555 = "        h ^= h >> 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v2555; }
    { const char * tb_v2556 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2556; }
    { const char * tb_v2557 = "    return h;\n"; *(const char * *)tb_grow(v_lines) = tb_v2557; }
    { const char * tb_v2558 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2558; }
    { const char * tb_v2559 = "static int tb_keq(tb_dict *d, const void *a, const void *b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2559; }
    { const char * tb_v2560 = "    if (d->text) return strcmp(*(const char * const *)a, *(const char * const *)b) == 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2560; }
    { const char * tb_v2561 = "    return *(const long long *)a == *(const long long *)b;\n"; *(const char * *)tb_grow(v_lines) = tb_v2561; }
    { const char * tb_v2562 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2562; }
    { const char * tb_v2563 = "static inline long long tb_dfind(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2563; }
    { const char * tb_v2564 = "    if (d->mode == 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2564; }
