    { const char * tb_v2581 = "        i = (i + 1) & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v2581; }
    { const char * tb_v2582 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2582; }
    { const char * tb_v2583 = "    return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2583; }
    { const char * tb_v2584 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2584; }
    { const char * tb_v2585 = "// память для таблиц dict — там же, где лежат его ключи (временная или обычная)\n"; *(const char * *)tb_grow(v_lines) = tb_v2585; }
    { const char * tb_v2586 = "static void *tb_dalloc(tb_dict *d, void *old, long long bytes) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2586; }
    { const char * tb_v2587 = "    if (old && !(tb_nchunks > 0 && tb_in_temp(old))) tb_gc_free(old);\n"; *(const char * *)tb_grow(v_lines) = tb_v2587; }
    { const char * tb_v2588 = "    void *p = tb_in_cur_temp(d->keys->data) ? tb_temp_alloc(bytes) : tb_gc_alloc_np(bytes);\n"; *(const char * *)tb_grow(v_lines) = tb_v2588; }
    { const char * tb_v2589 = "    if (!p) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2589; }
    { const char * tb_v2590 = "    return p;\n"; *(const char * *)tb_grow(v_lines) = tb_v2590; }
    { const char * tb_v2591 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2591; }
    { const char * tb_v2592 = "static void tb_dreindex(tb_dict *d, long long nslots) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2592; }
    { const char * tb_v2593 = "    d->mode = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2593; }
    { const char * tb_v2594 = "    if (d->pos) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2594; }
    { const char * tb_v2595 = "        if (!(tb_nchunks > 0 && tb_in_temp(d->pos))) tb_gc_free(d->pos);\n"; *(const char * *)tb_grow(v_lines) = tb_v2595; }
    { const char * tb_v2596 = "        d->pos = 0; d->npos = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2596; }
    { const char * tb_v2597 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2597; }
    { const char * tb_v2598 = "    d->nslots = nslots;\n"; *(const char * *)tb_grow(v_lines) = tb_v2598; }
    { const char * tb_v2599 = "    d->slots = tb_dalloc(d, d->slots, nslots * sizeof(long long));\n"; *(const char * *)tb_grow(v_lines) = tb_v2599; }
    { const char * tb_v2600 = "    memset(d->slots, 0, nslots * sizeof(long long));\n"; *(const char * *)tb_grow(v_lines) = tb_v2600; }
