    { const char * tb_v2602 = "    for (long long at = 0; at < d->keys->len; at++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2602; }
    { const char * tb_v2603 = "        unsigned long long h = tb_hash(d, d->keys->data + at * d->keys->size), i = h & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v2603; }
    { const char * tb_v2604 = "        while (d->slots[i] != 0) i = (i + 1) & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v2604; }
    { const char * tb_v2605 = "        d->slots[i] = (at + 1) | TB_DTAG(h);\n"; *(const char * *)tb_grow(v_lines) = tb_v2605; }
    { const char * tb_v2606 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2606; }
    { const char * tb_v2607 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2607; }
    { const char * tb_v2608 = "// перейти на таблицу с хешем (ключ ушёл далеко от остальных или его удалили)\n"; *(const char * *)tb_grow(v_lines) = tb_v2608; }
    { const char * tb_v2609 = "static void tb_dto_hash(tb_dict *d) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2609; }
    { const char * tb_v2610 = "    long long n = 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v2610; }
    { const char * tb_v2611 = "    while (n < d->keys->len * 2 + 2) n *= 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v2611; }
