    { const char * tb_v2613 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2613; }
    { const char * tb_v2614 = "// mode 2: таблица pos на ключи base .. base+npos-1\n"; *(const char * *)tb_grow(v_lines) = tb_v2614; }
    { const char * tb_v2615 = "static void tb_dto_pos(tb_dict *d, long long npos) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2615; }
    { const char * tb_v2616 = "    long long *p = tb_dalloc(d, 0, npos * sizeof(long long));\n"; *(const char * *)tb_grow(v_lines) = tb_v2616; }
