    { const char * tb_v2635 = "// .clear(): список снова пустой; свой кусок памяти отдаётся (если он не временный).\n"; *(const char * *)tb_grow(v_lines) = tb_v2635; }
    { const char * tb_v2636 = "// Тексты и obj внутри не удаляются: на них могут смотреть другие переменные.\n"; *(const char * *)tb_grow(v_lines) = tb_v2636; }
    { const char * tb_v2637 = "static void tb_lclear(tb_list *l, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2637; }
    { const char * tb_v2638 = "    if (l->cap < 0) tb_crash(line, \".clear() нельзя, пока по списку идёт each ... by N\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2638; }
    { const char * tb_v2639 = "    int temp = tb_nchunks > 0 && tb_in_temp(l->data);\n"; *(const char * *)tb_grow(v_lines) = tb_v2639; }
