    { const char * tb_v2688 = "        return v;\n"; *(const char * *)tb_grow(v_lines) = tb_v2688; }
    { const char * tb_v2689 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2689; }
    { const char * tb_v2690 = "    if (d->keys->len * 2 > d->nslots) tb_dreindex(d, d->nslots * 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v2690; }
    { const char * tb_v2691 = "    else {\n"; *(const char * *)tb_grow(v_lines) = tb_v2691; }
