    { const char * tb_v2747 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2747; }
    { const char * tb_v2748 = "// ---------- obj: память ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2748; }
    { const char * tb_v2749 = "// Внутри temp и шага цикла — из временной памяти, иначе — из памяти с уборкой.\n"; *(const char * *)tb_grow(v_lines) = tb_v2749; }
    { const char * tb_v2750 = "static void *tb_obj_mem(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2750; }
    { const char * tb_v2751 = "    if (tb_temp_depth > 0) return tb_mem(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v2751; }
