    { const char * tb_v2764 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2764; }
    { const char * tb_v2765 = "// a.wait: дождаться потока (один раз) и отдать адрес ответа\n"; *(const char * *)tb_grow(v_lines) = tb_v2765; }
