    { const char * tb_v2776 = "    long long last = d->keys->len - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2776; }
    { const char * tb_v2777 = "    // на место удалённого ставим последний: порядок меняется только у него\n"; *(const char * *)tb_grow(v_lines) = tb_v2777; }
    { const char * tb_v2778 = "    memcpy(d->keys->data + at * d->keys->size, d->keys->data + last * d->keys->size, d->keys->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v2778; }
    { const char * tb_v2779 = "    memcpy(d->vals->data + at * d->vals->size, d->vals->data + last * d->vals->size, d->vals->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v2779; }
    { const char * tb_v2780 = "    d->keys->len -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2780; }
    { const char * tb_v2781 = "    d->vals->len -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2781; }
